/**
 * (CLOUD-SEVERANCE-P2) The CLI's view of the frozen local organization.
 *
 * This MUST agree with the desktop app's resolver
 * (`apps/desktop/src/main/lib/local-identity/local-org.ts`) — the CLI finds a
 * running host-service by reading `~/.superset/host/<orgId>/manifest.json`, so
 * a different answer here means the CLI talks to a host that does not exist
 * while the app talks to the one that does.
 *
 * It is deliberately a READER, not a second resolver: the app decides and
 * records the id, and this file only ever reads that decision (falling back to
 * the same "one host database" scan if the CLI runs before the app has ever
 * started). It never mints and never writes — a CLI invocation must not be able
 * to define the identity the whole app runs under.
 */

import { existsSync, readdirSync, readFileSync } from "node:fs";
import { join } from "node:path";
import { SUPERSET_HOME_DIR } from "./config";

const UUID_PATTERN =
	/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

export function resolveLocalOrganizationId(): string | undefined {
	const decisionFile = join(SUPERSET_HOME_DIR, "fork-local-org.json");
	if (existsSync(decisionFile)) {
		try {
			const raw = JSON.parse(readFileSync(decisionFile, "utf-8")) as {
				organizationId?: unknown;
			};
			if (
				typeof raw.organizationId === "string" &&
				UUID_PATTERN.test(raw.organizationId)
			) {
				return raw.organizationId;
			}
		} catch {
			// Fall through to the scan; the app fails loud on a corrupt file and
			// the CLI should not be the thing that reports it.
		}
	}

	const hostRoot = join(SUPERSET_HOME_DIR, "host");
	if (!existsSync(hostRoot)) return undefined;
	const candidates = readdirSync(hostRoot, { withFileTypes: true })
		.filter((entry) => entry.isDirectory() && UUID_PATTERN.test(entry.name))
		.filter((entry) => existsSync(join(hostRoot, entry.name, "host.db")))
		.map((entry) => entry.name);
	// Exactly one, or nothing: guessing between two would point the CLI at a
	// different database than the app.
	return candidates.length === 1 ? candidates[0] : undefined;
}
