    override fun postLostContact(workingCount: Int, needsInputCount: Int) {
        if (!canPost()) {
            refreshDelivery()
            Log.w(TAG, "notification permission not granted; lost-contact warning not posted")
            return
        }
        val notification = NotificationCompat.Builder(context, CHANNEL_LIVENESS)
            .setSmallIcon(R.drawable.ic_notification)
            .setContentTitle("Lost contact with the desktop")
            .setContentText(
                "$needsInputCount waiting, $workingCount working at last contact. " +
                    "Agents keep running when Superset closes.",
            )
            .setStyle(
                NotificationCompat.BigTextStyle().bigText(
                    "$needsInputCount waiting for an answer and $workingCount working when the " +
                        "desktop last answered. The agents keep running under the detached pty " +
                        "daemon even though the bridge is gone, so this may need attention at " +
                        "the machine.",
                ),
            )
            .setContentIntent(openAppIntent(null))
            .setCategory(Notification.CATEGORY_STATUS)
            .setAutoCancel(true)
            // The watchdog can re-assert lost contact on any diagnostics change while the
            // desktop is still gone. Updating the counts in place is right; alerting again
            // for the same outage is not.
            .setOnlyAlertOnce(true)
            .build()
        manager.notify(TAG_LIVENESS, ID_LIVENESS, notification)
    }

    override fun cancelLostContact() = manager.cancel(TAG_LIVENESS, ID_LIVENESS)

