    /** The Data Layer kind token back to the protocol kind the identity rule speaks. */
    private fun kindOf(wireKind: String): LifecycleKind =
        if (wireKind == WatchLifecycleKind.READY) LifecycleKind.READY else LifecycleKind.ERROR

    private fun ensureChannel(context: Context, presentation: LifecycleAlertText) {
        val manager = context.getSystemService(NotificationManager::class.java)
        if (manager.getNotificationChannel(presentation.channelId) != null) return
        val channel = NotificationChannel(
            presentation.channelId,
            presentation.channelName,
            if (presentation.vibrates) {
                NotificationManager.IMPORTANCE_HIGH
            } else {
                NotificationManager.IMPORTANCE_DEFAULT
            },
        ).apply {
            description = presentation.channelDescription
            enableVibration(presentation.vibrates)
            setShowBadge(false)
        }
        manager.createNotificationChannel(channel)
    }
